 import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, BoxGeometry, DirectionalLight, PointLight, Color } = THREE;

  const visuals = config.intent?.visualSpec ?? {};
  const colors = visuals.colors ?? {};
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#14141a' }];
  const paper = colors.paper ?? '#e8ecf2';
  const ink = colors.ink ?? '#16161d';
  const accent = colors.accent ?? '#ff2a38';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Inside the atelier' };
  const captionTexts = items
    .filter((i) => i.role === 'caption')
    .map((i) => i.text);
  const defaultCaptions = ['DIAL ROOM', 'ESCAPEMENT BENCH', 'CNC HALL', 'FINISHING LAB', 'ARCHIVE VAULT', 'ASSEMBLY LINE ONE'];
  while (captionTexts.length < 6) captionTexts.push(defaultCaptions[captionTexts.length]);

  const group = new Group();
  group.userData.handlers = {};

  // Backdrop gradient.
  const bgGeo = new PlaneGeometry(7, 6);
  const grad = mix(color(stops[0].hex), color(stops[1].hex), smoothstep(0, 1, uv().y));
  const bgMat = new MeshBasicNodeMaterial({ colorNode: grad });
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.z = -2.5;
  group.add(bgMesh);

  // Lighting.
  const key = new DirectionalLight(new Color(paper), 1.0);
  key.position.set(3, 4, 6);
  group.add(key);
  const rim = new DirectionalLight(new Color(accent), 0.8);
  rim.position.set(-4, 2, 3.5);
  group.add(rim);
  const fill = new PointLight(new Color(paper), 0.45, 20, 2);
  fill.position.set(0, -1, 4);
  group.add(fill);

  // Headline.
  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 68,
    color: paper,
    align: 'left',
  });
  headline.position.set(-1.6, 1.9, 0.15);
  group.add(headline);

  function setOpacity(obj, value) {
    obj.traverse((child) => {
      if (child.isMesh && child.material) {
        child.material.transparent = true;
        child.material.opacity = value;
        child.material.needsUpdate = true;
      }
    });
  }

  // Captions.
  const captionObjs = captionTexts.map((text) => {
    const obj = ctx.fontAtlas.createText(text, {
      fontSize: 18,
      color: paper,
      align: 'left',
    });
    setOpacity(obj, 0);
    obj.position.set(-1.6, 0, 0.15);
    group.add(obj);
    return { obj, state: { opacity: 0 } };
  });

  // Column plates.
  const plateW = 1.9;
  const plateH = 1.2;
  const pitch = 1.5;
  const plateCount = 6;
  const total = pitch * plateCount;

  const platesGroup = new Group();
  platesGroup.position.x = 0.9;
  group.add(platesGroup);

  const frameMat = new MeshPhysicalNodeMaterial({
    color: new Color(ink),
    roughness: 0.5,
    metalness: 0.5,
    clearcoat: 0.25,
  });

  const stripGeo = new PlaneGeometry(0.03, plateH * 0.94);
  const stripMat = new MeshPhysicalNodeMaterial({
    color: new Color(accent),
    emissive: new Color(accent),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.1,
  });

  const plateGeo = new PlaneGeometry(plateW, plateH);
  const frameGeo = new BoxGeometry(plateW + 0.06, plateH + 0.06, 0.04);

  const plates = [];
  const gradeTints = ['#ffffff', '#f5f0e6', '#e8eef5', '#f0e8ec', '#e8f2ec', '#f2efe8'];

  for (let i = 0; i < plateCount; i++) {
    const root = new Group();
    root.userData.index = i;

    const frame = new THREE.Mesh(frameGeo, frameMat);
    frame.position.z = -0.02;
    root.add(frame);

    const photoMat = new MeshPhysicalNodeMaterial({
      color: new Color(gradeTints[i]),
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
    });
    const photo = new THREE.Mesh(plateGeo, photoMat);
    photo.position.z = 0.02;
    root.add(photo);

    const strip = new THREE.Mesh(stripGeo, stripMat);
    strip.position.set(-plateW / 2 - 0.015, 0, 0.04);
    strip.visible = false;
    root.add(strip);

    platesGroup.add(root);
    plates.push({ root, photoMat, strip });
  }

  // Texture load / distinct plate variants.
  const imageUrl = config.imageUrl ?? '/prism-mock/home/nodes/feature-card.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.ClampToEdgeWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.needsUpdate = true;

    plates.forEach((p, i) => {
      const cloned = tex.clone();
      cloned.repeat.set(0.9, 0.9);
      cloned.offset.set((i * 0.08) % 0.5, (i * 0.05) % 0.5);
      cloned.needsUpdate = true;
      p.photoMat.map = cloned;
      p.photoMat.needsUpdate = true;
      p.texture = cloned;
    });
  });

  // Scroll / loop logic.
